import{_ as t,o,c as a,a3 as r}from"./chunks/framework.CVt6dz2a.js";const d="/threejs-tutorial-site/assets/EP.33-one-scene-many-screens.DTXSM_ea.svg",q=JSON.parse('{"title":"EP.33 一套场景，多块屏幕","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.33-one-scene-many-screens.md","filePath":"comics/EP.33-one-scene-many-screens.md","lastUpdated":1793881879000}'),c={name:"comics/EP.33-one-scene-many-screens.md"};function s(n,e,i,l,u,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="ep-33-一套场景-多块屏幕" tabindex="-1">EP.33 一套场景，多块屏幕 <a class="header-anchor" href="#ep-33-一套场景-多块屏幕" aria-label="Permalink to &quot;EP.33 一套场景，多块屏幕&quot;">​</a></h1><p><img src="'+d+'" alt="EP.33 一景多屏：像素酱、码叔与标签君讨论同一场景如何跑在 Web、小程序与小游戏上"></p><blockquote><p><strong>对应正文</strong>：<a href="./../guide/33-cross-platform/basics">33.1 基础入门：Vue 3 + TresJS 声明式 3D</a><strong>延伸阅读</strong>：<a href="./../guide/33-cross-platform/advanced">33.2 进阶应用：小程序 / 小游戏端的三.js 适配</a> · <a href="./../guide/33-cross-platform/practice">33.3 实战案例：一套场景多端交付</a><strong>动手演示</strong>：<a href="./../public/demos/cross-platform/declarative-vs-imperative.html">declarative-vs-imperative 声明式 vs 命令式</a> · <a href="./../public/demos/cross-platform/platform-adapter-lab.html">platform-adapter-lab 平台约束模拟器</a> · <a href="./../public/demos/cross-platform/multitarget-lab.html">multitarget-lab 多端交付台</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>画面</th><th>关键对白</th><th>梗 / 记忆点</th></tr></thead><tbody><tr><td>1</td><td>像素酱在 Web 上信心满满，切到小程序直接黑屏；标签君抱着 2048 贴图</td><td>&quot;Web 上跑得好好的，小程序里怎么直接黑屏？&quot; / &quot;贴图 2048 塞进小游戏，包体当场就爆了。&quot;</td><td>浏览器白送的 <code>new Image()</code>、<code>requestAnimationFrame</code>、<code>pointerdown</code>，换端全要自己补</td></tr><tr><td>2</td><td>码叔推了推眼镜，画出四块拼图：canvas shim、WebGL ctx、ImageLoader、rAF / touch</td><td>&quot;没有 DOM？先给 three 补一个最小可用的宿主。&quot;</td><td>适配层的本质是&quot;补宿主&quot;，不是&quot;改 three&quot;</td></tr><tr><td>3</td><td>三端能力清单摊在桌上：纹理、事件、包体、切后台</td><td>&quot;同一份场景，三端上限完全不同。&quot;</td><td>降级靠能力清单，不靠散落各处的 <code>if</code></td></tr><tr><td>4</td><td>码叔总结三条纪律，标签君把坑点贴到墙上</td><td>&quot;先定能力清单，再谈一套代码多端跑。&quot;</td><td>平台判断、纹理规格、后台不停渲染，是跨端三连坑</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-浏览器不是-默认环境-只是其中一种宿主" tabindex="-1">1. 浏览器不是&quot;默认环境&quot;，只是其中一种宿主 <a class="header-anchor" href="#_1-浏览器不是-默认环境-只是其中一种宿主" aria-label="Permalink to &quot;1. 浏览器不是&quot;默认环境&quot;，只是其中一种宿主&quot;">​</a></h3><p>Three.js 写的是一套与宿主无关的渲染抽象，但它默认依赖浏览器的几样东西：<code>window</code>、<code>document.createElement(&#39;canvas&#39;)</code>、<code>new Image()</code>、<code>requestAnimationFrame</code>、Pointer Events。Web 端这些能力是白送的，小程序 / 小游戏则要自己补。适配层的工作就是把这些&quot;默认环境&quot;补回来，让原版 three 代码以为自己还在浏览器里。</p><h3 id="_2-适配层要补的是一条链-而不是一个点" tabindex="-1">2. 适配层要补的是一条链，而不是一个点 <a class="header-anchor" href="#_2-适配层要补的是一条链-而不是一个点" aria-label="Permalink to &quot;2. 适配层要补的是一条链，而不是一个点&quot;">​</a></h3><p><code>canvas</code> 与 <code>WebGLRenderingContext</code> 只是第一层。真正的资产链还包括：图片加载（<code>ImageLoader</code>）、文件加载（<code>FileLoader</code> / glTF）、动画循环（rAF 补丁）、事件（触摸映射）、生命周期（<code>onHide</code> / <code>onShow</code>）。只补 canvas 不补加载器，场景能亮但贴图全是黑的；只补加载器不补 rAF，画面永远停在第一帧。</p><h3 id="_3-能力清单是跨端的-单一事实来源" tabindex="-1">3. 能力清单是跨端的&quot;单一事实来源&quot; <a class="header-anchor" href="#_3-能力清单是跨端的-单一事实来源" aria-label="Permalink to &quot;3. 能力清单是跨端的&quot;单一事实来源&quot;&quot;">​</a></h3><p>能力清单描述当前环境支持什么：最大纹理、DPR 上限、有没有实时阴影、用哪种事件模型、包体预算是多少。场景描述只写&quot;要什么&quot;，运行时按清单决定&quot;给多少&quot;。这样同一份场景在三端都能执行，而不是在业务代码里写三套分支。</p><h3 id="_4-跨端不是同端降级" tabindex="-1">4. 跨端不是同端降级 <a class="header-anchor" href="#_4-跨端不是同端降级" aria-label="Permalink to &quot;4. 跨端不是同端降级&quot;">​</a></h3><p>㉕ 的降级阶梯是同一浏览器里&quot;关特效、降 DPR&quot;；跨端是换掉整个运行环境：DOM 没了、加载器换了、事件换了、生命周期换了、包体有硬上限。所以跨端的架构单位不是&quot;一个场景一条阶梯&quot;，而是&quot;一份场景描述 + 多个运行时适配器&quot;。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li><strong>误区一：把 TresJS 直接搬到小程序。</strong> TresJS 的宿主是浏览器 DOM，<code>TresCanvas</code> 依赖 <code>document</code>、<code>ResizeObserver</code> 和标准事件模型，小程序端不能照搬；它更适合作为 Web 运行时的那一层。</li><li><strong>误区二：只补 canvas，不补加载器。</strong> 贴图黑、模型空、字体不显示，八成是 <code>ImageLoader</code> / <code>FileLoader</code> 还在走浏览器实现。</li><li><strong>误区三：切后台只停循环，不释放资源。</strong> 后台占着纹理与 RenderTarget，iOS 上更容易被系统回收，回来时可能直接上下文丢失。</li><li><strong>误区四：纹理规格跟着美术走。</strong> 2048 贴图在 Web 上没问题，进了 4MB 主包的小游戏就是事故。</li></ul><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><details><summary><b>Q1：适配层最该先补哪三个接口？</b></summary><p>优先补 <code>canvas</code> + <code>WebGLRenderingContext</code>（让渲染器能创建）、<code>Image</code> / 图片加载（让纹理能上传）、<code>requestAnimationFrame</code>（让循环能跑）。这三条打通，才能看到&quot;有画面的场景&quot;；之后再补文件加载、触摸事件、生命周期与上下文恢复。</p></details><details><summary><b>Q2：为什么小程序里 `delta` 会突然变得很大？</b></summary><p>因为切后台期间渲染循环没有真正暂停，或暂停后没有重置计时器，恢复时 <code>delta</code> 累计了整段后台时间。修复方式是 <code>onHide</code> 停循环，<code>onShow</code> 先重置计时器再恢复，让逻辑时间从暂停点继续。</p></details><details><summary><b>Q3：&quot;一套代码多端跑&quot;最现实的做法是什么？</b></summary><p>把可复用的部分抽成&quot;场景描述 + 能力清单 + 运行时接口&quot;，平台差异全部收敛到适配器。业务层只依赖 <code>RuntimeAdapter</code> 的挂载、逐帧、尺寸、暂停、恢复、销毁、输入这几个方法，不直接写平台判断。这样 Web 端可以用 Vue + TresJS，小程序端换 three 适配层，场景描述仍然是同一份。</p></details><hr><blockquote><p>下一篇正文见 <a href="./../guide/33-cross-platform/basics">33.1 基础入门：Vue 3 + TresJS 声明式 3D</a>。漫画仅作概念预热，代码与验收细节以正文为准。</p></blockquote>',22)])])}const p=t(c,[["render",s]]);export{q as __pageData,p as default};
